        "ProfissionalId" integer,
        "ResponsavelId" integer,
        "ProximoContato" date NOT NULL,
        "Etapa" character varying(30) NOT NULL,
        "CriadoEm" timestamp without time zone NOT NULL,
        "CriadoPor" character varying(80) NOT NULL,
        "EncerradoEm" timestamp without time zone,
        "MotivoEncerramento" character varying(2000),
        "EncerradoPor" character varying(80),
        "MotivoId" integer,
        "Versao" uuid NOT NULL,
        CONSTRAINT "PK_Acompanhamentos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Acompanhamentos_Agendamentos_AgendamentoOrigemId" FOREIGN KEY ("AgendamentoOrigemId") REFERENCES "Agendamentos" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Acompanhamentos_MotivosAcompanhamento_MotivoId" FOREIGN KEY ("MotivoId") REFERENCES "MotivosAcompanhamento" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Acompanhamentos_Pacientes_PacienteId" FOREIGN KEY ("PacienteId") REFERENCES "Pacientes" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Acompanhamentos_Profissionais_ProfissionalId" FOREIGN KEY ("ProfissionalId") REFERENCES "Profissionais" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Acompanhamentos_Usuarios_ResponsavelId" FOREIGN KEY ("ResponsavelId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

