        "Idempotencia" uuid NOT NULL,
        "Em" timestamp without time zone NOT NULL,
        "Operador" character varying(80) NOT NULL,
        "Canal" character varying(20),
        "Resultado" character varying(100) NOT NULL,
        "Observacao" character varying(2000) NOT NULL,
        "ProximoContato" date,
        "ResponsavelId" integer,
        CONSTRAINT "PK_ContatosAcompanhamento" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ContatosAcompanhamento_Acompanhamentos_AcompanhamentoPacien~" FOREIGN KEY ("AcompanhamentoPacienteId") REFERENCES "Acompanhamentos" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_ContatosAcompanhamento_Usuarios_ResponsavelId" FOREIGN KEY ("ResponsavelId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
